{
  "case_id": "xsu_sg_013_specialist_declaration",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Svaret gengiver korrekt, at Udbetaling Danmark i særlige tilfælde kan bede om en speciallægeerklæring, når dokumentationen ikke tilstrækkeligt beskriver art og grad. Det nævner alle fire eksempelgrupper og at Udbetaling Danmark betaler udgifterne. Ingen af de væsentlige fejl i rubrikken er begået."},
    "c02_required_elements_complete": {"label": "met", "reason": "Begge kritiske elementer er med: muligheden i særlige tilfælde ved utilstrækkelig beskrivelse af art og grad, og alle fire eksempelgrupper (intensitet/hyppighed, diskrepans, tvivl om behandling/prognose, tvivl om hverdag vs. ferie). Det understøttende element om betaling er også med."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer direkte, hvornår Udbetaling Danmark kan bede om en speciallægeerklæring, uden irrelevant tekst."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde, hverken bestemmelse eller vejledningsafsnit. Efter reglen er C04 derfor not_met."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke bedømmes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke bedømmes."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Alle udsagn svarer til vejledningens afsnit 5.1.3.2. Svaret tilføjer ingen ukendte regler, betingelser eller myndigheder."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "'I særlige tilfælde' og 'kan' er bevaret. Eksemplerne er markeret som eksempler med 'for eksempel'. 'Stor tvivl' er bevaret for gruppen om behandlingsmuligheder, prognose og funktionsniveau. Det er ikke gjort til en automatisk pligt."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er sammenhængende: først hovedreglen, derefter eksempler og til sidst udgiftsdækningen. Der er ingen modstrid."},
    "c10_legal_modality_precision": {"label": "met", "reason": "Modaliteten er præcis: 'kan i særlige tilfælde' og 'for eksempel'. Svaret gør hverken muligheden til en pligt eller eksemplerne til en udtømmende liste. 'Betaler' svarer til kilden."}
  },
  "xhaile_coverage": {
    "A74": {"label": "yes", "reason": "Svaret dækker, at der i særlige tilfælde kan indhentes en speciallægeerklæring, når art og grad ikke er tilstrækkeligt beskrevet. Alle fire eksempler er med i sammenhæng med kildens indhold."}
  },
  "overall_notes": "Indholdet er juridisk korrekt og komplet i forhold til rubrikken og vejledningen. Eneste mangel er, at svaret ikke angiver nogen kilde, hvilket giver not_met på C04 og not_assessable på C05 og C06."
}

